//! The weather service: the weather fixture's operations, generated by
//! build.rs from the `weather-model` package, implemented over a
//! [`CityStore`]. The service type holds dependencies, never data, so any
//! number of instances (Lambda, ECS tasks) serve the same cities.
//!
//! Test hook: `x-fail-times: N` with `x-fail-key: K` answers the first N
//! requests under that key with a throttling error. It is a handler, not part
//! of any operation, the way a real service's throttling would be.

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use crucible::handlers::{ExceptionTranslator, ServiceLog};
use crucible::validate::Rejection;
use crucible::{Crucible, Handler, InvokeProtocol, Job, JsonProtocol, WithContext};

pub mod api {
    crucible::include_service!();
}
mod store;

pub use store::{CityStore, MemoryCities, NameTaken, NewCity};

use api::errors::{ConflictError, NotFoundError, ThrottlingError};
use api::model::{
    CreateCityInput, CreateCityOutput, GetCityInput, GetCityOutput, ListCitiesInput,
    ListCitiesOutput, Sky, StatusInput, StatusOutput,
};

/// Implements every operation. Shared by all requests: it holds clients and
/// configuration, never per-request or persistent data.
pub struct Weather {
    cities: Arc<dyn CityStore>,
}

impl Weather {
    pub fn new(cities: Arc<dyn CityStore>) -> Self {
        Self { cities }
    }
}

impl api::PingOperation for Weather {
    async fn ping(&self) -> crucible::Result<()> {
        Ok(())
    }
}

impl api::StatusOperation for Weather {
    async fn status(&self, _: StatusInput) -> crucible::Result<StatusOutput> {
        Ok(StatusOutput {})
    }
}

impl api::CreateCityOperation for Weather {
    async fn create_city(&self, input: CreateCityInput) -> crucible::Result<CreateCityOutput> {
        let city = NewCity {
            name: input.name,
            // The expected revision stands in for a population, so a test can
            // see a header member arrive.
            population: input.expected_revision.unwrap_or(0),
        };
        // A taken name is the store's `NameTaken`; the exception translator
        // answers it as `ConflictError`.
        let city = self
            .cities
            .create(city, input.client_token.as_deref())
            .await?;
        Ok(CreateCityOutput { city })
    }
}

impl api::GetCityOperation for Weather {
    async fn get_city(&self, input: GetCityInput) -> crucible::Result<GetCityOutput> {
        let Some(city) = self.cities.get(&input.city_id).await? else {
            return Err(NotFoundError {
                message: "no such city".to_owned(),
                resource_id: Some(input.city_id),
            }
            .into());
        };
        // Echoes the query timestamp, so a test can see it arrive intact.
        let forecast = input
            .at
            .map(|at| BTreeMap::from([(Sky::Clear, serde_json::json!({ "at": at.to_rfc3339() }))]));
        Ok(GetCityOutput {
            city,
            forecast,
            // An operation can model the request-id header itself; the
            // framework's own id is on the context.
            request_id: Some(if self.context().request_id().is_empty() {
                "no context".to_owned()
            } else {
                "req-from-server".to_owned()
            }),
        })
    }
}

impl api::ListCitiesOperation for Weather {
    async fn list_cities(&self, input: ListCitiesInput) -> crucible::Result<ListCitiesOutput> {
        let size = input.max_results.unwrap_or(100) as usize;
        // The fixture's cities have no tags, so a tag filters by name.
        let names = input.tags.unwrap_or_default();
        // One more than a page says whether another page follows.
        let mut cities = self
            .cities
            .list(input.next_token.as_deref(), size + 1, &names)
            .await?;
        let next_token = (cities.len() > size).then(|| {
            cities.truncate(size);
            cities.last().map(|city| city.id.clone())
        });
        Ok(ListCitiesOutput {
            cities,
            next_token: next_token.flatten(),
        })
    }
}

/// The throttling test hook; see the module docs.
#[derive(Default)]
struct FailTimes {
    seen: Mutex<BTreeMap<String, u32>>,
}

#[crucible::async_trait]
impl Handler for FailTimes {
    async fn before(&self, job: &mut Job) -> crucible::Result<()> {
        let header = |name: &str| {
            job.request()
                .headers
                .get(name)
                .and_then(|v| v.to_str().ok())
                .map(str::to_owned)
        };
        let (Some(times), Some(key)) = (header("x-fail-times"), header("x-fail-key")) else {
            return Ok(());
        };
        let times: u32 = times
            .parse()
            .map_err(|_| Rejection::malformed("x-fail-times", "must be a whole number"))?;
        let mut seen = self.seen.lock().unwrap();
        let count = seen.entry(key).or_default();
        if *count < times {
            *count += 1;
            return Err(ThrottlingError {
                message: "slow down".to_owned(),
                retry_after: Some(0),
            }
            .into());
        }
        Ok(())
    }
}

/// The service over `cities`: every operation on one `Weather`, the default
/// chain plus the test hook, and the store's errors translated.
pub fn service(cities: Arc<dyn CityStore>) -> Crucible {
    let translator = ExceptionTranslator::new().translate(|taken: &NameTaken| {
        ConflictError {
            message: taken.to_string(),
        }
        .into()
    });
    Crucible::builder(api::operations(Arc::new(Weather::new(cities))))
        .handler(ServiceLog::errors_only())
        .handler(translator)
        .handler(FailTimes::default())
        .handler(JsonProtocol)
        .handler(InvokeProtocol)
        .build()
        .expect("the weather service builds")
}
